import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10, default 10).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error('Unknown tool: ' + name);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['query', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Invalid argument "' + key + '": unknown property');
    }
  }

  const query = args.query;
  if (typeof query !== 'string') {
    throw new Error('Invalid argument "query": expected a string');
  }

  let limit = args.limit === undefined ? 10 : args.limit;
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 10) {
    throw new Error('Invalid argument "limit": expected an integer between 1 and 10');
  }

  const needle = query.toLowerCase();
  const matches = products
    .filter((p) => p.name.toLowerCase().includes(needle))
    .slice(0, limit);

  const text = matches.length === 0
    ? 'No products found.'
    : matches.map((p) => `${p.id}: ${p.name}`).join('\n');

  return { content: [{ type: 'text', text }] };
}
